Contents of file src/components/LanguageContext.tsx:

1 | "use client";
2 | 
3 | import { createContext, useContext, useEffect, useState, ReactNode } from "react";
4 | import { Lang, t as translate } from "@/lib/i18n";
5 | 
6 | interface AppContextValue {
7 |   lang: Lang;
8 |   setLang: (l: Lang) => void;
9 |   theme: "dark" | "light";
10 |   toggleTheme: () => void;
11 |   t: (key: Parameters<typeof translate>[1]) => string;
12 | }
13 | 
14 | const AppContext = createContext<AppContextValue | null>(null);
15 | 
16 | export function AppProvider({ children }: { children: ReactNode }) {
17 |   const [lang, setLangState] = useState<Lang>("en");
18 |   const [theme, setTheme] = useState<"dark" | "light">("dark");
19 |   const [themeReady, setThemeReady] = useState(false);
20 | 
21 |   useEffect(() => {
22 |     const storedLang = localStorage.getItem("ssb_lang") as Lang | null;
23 |     const storedTheme = localStorage.getItem("ssb_theme") as "dark" | "light" | null;
24 |     if (storedLang) setLangState(storedLang);
25 |     if (storedTheme) setTheme(storedTheme);
26 |     setThemeReady(true);
27 |   }, []);
28 | 
29 |   useEffect(() => {
30 |     if (!themeReady) return;
31 |     document.documentElement.classList.toggle("light", theme === "light");
32 |     document.documentElement.classList.toggle("dark", theme === "dark");
33 |     document.documentElement.style.colorScheme = theme;
34 |     localStorage.setItem("ssb_theme", theme);
35 |   }, [theme, themeReady]);
36 | 
37 |   const setLang = (l: Lang) => {
38 |     setLangState(l);
39 |     localStorage.setItem("ssb_lang", l);
40 |   };
41 | 
42 |   const toggleTheme = () => {
43 |     const next = theme === "dark" ? "light" : "dark";
44 |     setTheme(next);
45 |   };
46 | 
47 |   return (
48 |     <AppContext.Provider value={{ lang, setLang, theme, toggleTheme, t: (k) => translate(lang, k) }}>
49 |       <div className={lang === "bn" ? "font-bn" : ""}>{children}</div>
50 |     </AppContext.Provider>
51 |   );
52 | }
53 | 
54 | export function useApp() {
55 |   const ctx = useContext(AppContext);
56 |   if (!ctx) throw new Error("useApp must be used within AppProvider");
57 |   return ctx;
58 | }
59 |

