109 | export function localizeError(lang: Lang, raw: unknown): string {
110 |   const msg = raw instanceof Error ? raw.message : String(raw ?? "");
111 |   if (lang === "en") return msg || "Something went wrong";
112 |   for (const e of ERROR_MAP) {
