119 | export function levenshtein(a: string, b: string): number {
120 |   const m = a.length;
121 |   const n = b.length;
122 |   if (m === 0) return n;
123 |   if (n === 0) return m;
124 |   const dp: number[][] = Array.from({ length: m + 1 }, (_, i) => [i, ...Array(n).fill(0)]);
125 |   for (let j = 1; j <= n; j++) dp[0][j] = j;
126 |   for (let i = 1; i <= m; i++) {
127 |     for (let j = 1; j <= n; j++) {
128 |       dp[i][j] =
129 |         a[i - 1] === b[j - 1]
130 |           ? dp[i - 1][j - 1]
131 |           : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
132 |     }
133 |   }
134 |   return dp[m][n];
135 | }
