137 | export function isNearDuplicate(a: string, b: string): boolean {
138 |   const x = a.trim().toLowerCase();
139 |   const y = b.trim().toLowerCase();
140 |   if (!x || !y || x === y) return false;
141 |   if (x.includes(y) || y.includes(x)) return true;
142 |   const dist = levenshtein(x, y);
143 |   const maxLen = Math.max(x.length, y.length);
144 |   return dist <= 2 || (maxLen > 10 && dist / maxLen <= 0.15);
145 | }
